/// <summary>
/// Xuất excel theo cơ chế mới: tự sinh file .xls dạng HTML/SpreadsheetML bằng UTF-8,
/// không dùng Excel COM Interop nên không bị lỗi NullReferenceException trên máy thiếu Office.
/// Xuất đúng các cột đang hiển thị trên màn hình tìm kiếm (caption và text hiển thị của ô).
/// </summary>
private void ExportCurrentViewToExcel2()
{
    if (gvData.RowCount <= 0)
    {
        MessageManager.Info("Không có dữ liệu để xuất excel!");
        return;
    }
    List<BandedGridColumn> columns = GetVisibleExportColumns();
    if (columns.Count == 0)
    {
        MessageManager.Info("Không có cột dữ liệu hiển thị để xuất excel!");
        return;
    }
    SaveFileDialog dlg = new SaveFileDialog();
    dlg.Filter = "Excel 97-2003 (*.xls)|*.xls";
    dlg.FileName = "LichThi_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".xls";
    dlg.Title = "Xuất excel";
    if (dlg.ShowDialog() != DialogResult.OK)
        return;
    try
    {
        StringBuilder sb = new StringBuilder();
        sb.AppendLine("<html xmlns:o=\"urn:schemas-microsoft-com:office:office\" xmlns:x=\"urn:schemas-microsoft-com:office:excel\" xmlns=\"http://www.w3.org/TR/REC-html40\">");
        sb.AppendLine("<head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />");
        sb.AppendLine("<style>td,th{border:1px solid #999;mso-number-format:'\\@';font-family:Tahoma;font-size:10pt;} th{font-weight:bold;background:#D9E1F2;text-align:center;}</style>");
        sb.AppendLine("</head><body><table cellspacing=\"0\" cellpadding=\"3\">");
        sb.AppendLine("<tr>");
        foreach (BandedGridColumn column in columns)
            sb.Append("<th>").Append(EncodeExcelText(GetColumnCaption(column))).AppendLine("</th>");
        sb.AppendLine("</tr>");
        for (int i = 0; i < gvData.RowCount; i++)
        {
            sb.AppendLine("<tr>");
            foreach (BandedGridColumn column in columns)
            {
                string value = gvData.GetRowCellDisplayText(i, column);
                sb.Append("<td>").Append(EncodeExcelText(value)).AppendLine("</td>");
            }
            sb.AppendLine("</tr>");
        }
        sb.AppendLine("</table></body></html>");
        File.WriteAllText(dlg.FileName, sb.ToString(), Encoding.UTF8);
        MessageManager.Info("Xuất excel thành công!");
    }
    catch (Exception objExc)
    {
        MessageManager.Error("Xuất excel bị lỗi: " + objExc.Message);
    }
}

/// <summary>
/// Lấy các cột đang hiển thị trên lưới, sắp xếp theo đúng thứ tự hiển thị.
/// </summary>
private List<BandedGridColumn> GetVisibleExportColumns()
{
    List<BandedGridColumn> columns = new List<BandedGridColumn>();
    foreach (BandedGridColumn column in gvData.Columns)
    {
        if (column.Visible && column.VisibleIndex >= 0 && !string.IsNullOrEmpty(column.FieldName))
            columns.Add(column);
    }
    columns.Sort(delegate(BandedGridColumn column1, BandedGridColumn column2)
    {
        return column1.VisibleIndex.CompareTo(column2.VisibleIndex);
    });
    return columns;
}

private string GetColumnCaption(BandedGridColumn column)
{
    if (!string.IsNullOrEmpty(column.Caption))
        return column.Caption;
    return column.FieldName;
}

private string EncodeExcelText(string value)
{
    if (value == null)
        return "";
    string encoded = SecurityElement.Escape(value);
    if (encoded == null)
        return "";
    return encoded.Replace("\r\n", "<br/>").Replace("\n", "<br/>").Replace("\r", "<br/>");
}

